     5	
     6	  belongs_to :account, default: -> { board.account }
     7	  belongs_to :board
     8	  belongs_to :creator, class_name: "User", default: -> { Current.user }
     9	
    10	  has_many :reactions, -> { order(:created_at) }, as: :reactable, dependent: :delete_all
    11	  has_one_attached :image, dependent: :purge_later
    12	
    13	  has_rich_text :description
    14	
    15	  before_save :set_default_title, if: :published?
    16	  before_create :assign_number
    17	
    18	  after_save   -> { board.touch }, if: :published?
    19	  after_touch  -> { board.touch }, if: :published?
    20	  after_update :handle_board_change, if: :saved_change_to_board_id?
    21	
    22	  scope :reverse_chronologically, -> { order created_at:     :desc, id: :desc }
    23	  scope :chronologically,         -> { order created_at:     :asc,  id: :asc  }
    24	  scope :latest,                  -> { order last_active_at: :desc, id: :desc }
    25	  scope :with_users,              -> { preload(creator: [ :avatar_attachment, :account ], assignees: [ :avatar_attachment, :account ]) }
    26	  scope :preloaded,               -> { with_users.preload(:column, :tags, :steps, :closure, :goldness, :activity_spike, :image_attachment, reactions: :reacter, board: [ :entropy, :columns ], not_now: [ :user ]).with_rich_text_description_and_embeds }
    27	
    28	  scope :indexed_by, ->(index) do
    29	    case index
    30	    when "stalled" then stalled
    31	    when "postponing_soon" then postponing_soon
    32	    when "closed" then closed
    33	    when "maybe" then awaiting_triage
    34	    when "not_now" then postponed.latest
    35	    when "golden" then golden
    36	    when "draft" then drafted
    37	    else all
    38	    end
    39	  end
    40	
    41	  scope :sorted_by, ->(sort) do
    42	    case sort
    43	    when "newest" then reverse_chronologically
    44	    when "oldest" then chronologically
